import { MakeLogicType, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { subscriptions } from 'kea-subscriptions'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { teamLogic } from 'scenes/teamLogic'

import { metricsHasRecentMetricsRetrieve } from 'products/metrics/frontend/generated/api'
import { canViewMetrics } from 'products/metrics/frontend/metricsAccess'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsInsightAvailabilityLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    currentTeamId: number | null // teamLogic
    hasRecentMetrics: boolean | null
    hasRecentMetricsLoading: boolean
    metricsFlagsEnabled: boolean
    showMetricsInsight: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsInsightAvailabilityLogicActions {
    loadHasRecentMetrics: () => any
    loadHasRecentMetricsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadHasRecentMetricsSuccess: (
        hasRecentMetrics: boolean | null,
        payload?: any
    ) => {
        hasRecentMetrics: boolean | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsInsightAvailabilityLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        metricsFlagsEnabled: (featureFlags: FeatureFlagsSet) => boolean
        showMetricsInsight: (metricsFlagsEnabled: boolean, hasRecentMetrics: boolean | null) => boolean
    }
}

export type metricsInsightAvailabilityLogicType = MakeLogicType<
    metricsInsightAvailabilityLogicValues,
    metricsInsightAvailabilityLogicActions,
    Record<string, any>,
    metricsInsightAvailabilityLogicMeta
>

export const metricsInsightAvailabilityLogic = kea<metricsInsightAvailabilityLogicType>([
    path(['scenes', 'insights', 'metricsInsightAvailabilityLogic']),
    connect(() => ({
        values: [featureFlagLogic, ['featureFlags'], teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        hasRecentMetrics: [
            null as boolean | null,
            {
                loadHasRecentMetrics: async () => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    try {
                        const response = await metricsHasRecentMetricsRetrieve(String(values.currentTeamId))
                        return response.hasRecentMetrics
                    } catch {
                        return false
                    }
                },
            },
        ],
    })),
    selectors({
        metricsFlagsEnabled: [
            (s) => [s.featureFlags],
            (featureFlags): boolean =>
                !!featureFlags[FEATURE_FLAGS.METRICS] && !!featureFlags[FEATURE_FLAGS.METRICS_INSIGHT_BUILDER],
        ],
        showMetricsInsight: [
            (s) => [s.metricsFlagsEnabled, s.hasRecentMetrics],
            (metricsFlagsEnabled, hasRecentMetrics): boolean => metricsFlagsEnabled && hasRecentMetrics === true,
        ],
    }),
    subscriptions(({ actions, values }) => ({
        metricsFlagsEnabled: (metricsFlagsEnabled: boolean) => {
            if (
                metricsFlagsEnabled &&
                canViewMetrics() &&
                values.hasRecentMetrics === null &&
                !values.hasRecentMetricsLoading
            ) {
                actions.loadHasRecentMetrics()
            }
        },
    })),
])
